if(!r.ok)throw new Error((d&&d.error)?d.error:('HTTP '+r.status));setText('rel-current',d.current||'--');setText('rel-latest',d.latest||d.tag||'--');setText('rel-artifact',d.artifact||'--');var msg='已是最新版本';var cls='v-ok';if(d.update&&d.url){releaseUpdateUrl=d.url;msg='发现新版本';cls='v-warn';if(install)install.disabled=false;setText('rel-msg','发现 '+(d.tag||d.latest)+'，点击“安装更新”后设备会下载并重启。');}else if(!d.url){msg='未找到匹配固件';cls='v-err';setText('rel-msg','Release 中没有 '+(d.artifact||'当前硬件')+' 对应的固件文件。');}else{setText('rel-msg','当前版本 '+(d.current||'--')+' 已不低于 '+(d.latest||'--')+'。');}
